# Using 8-way connectivity (adjacent cells)

def find_connected(grid, start, color):
    """Find all cells of given color connected to start position"""
    rows = len(grid)
    cols = len(grid[0])

    if grid[start[0]][start[1]] != color:
        return set()

    # Include cells of the specified color
    target_set = set((r,c) for r in range(rows) for c in range(cols) if grid[r][c] == color)

    if start not in target_set:
        return set()

    visited = set()
    queue = [start]

